  "ledtradar": [
    "Använd formeln \\(k=\\dfrac{y_2-y_1}{x_2-x_1}\\) från formelbladet.",
    "Hur mycket ökar \\(y\\) när \\(x\\) ökar från 1 till 3?"
  ],
